 52	/**
 53	This implementation implements the ADT with a map.
 54	 */
 55	class MultisetImplementationWithMap extends MyMultiset {
 56	
 57	  // valid invariant predicate of the ADT implementation
 58	  ghost predicate Valid()
 59	    reads this
 60	  {
 61	    (forall i | i in elements.Keys :: elements[i] > 0) && (theMultiset == A(elements)) && (forall i :: i in elements.Keys <==> Contains(i))
 62	  }
 63	
 64	  // the abstraction function
 65	  function A(m: map<int, nat>): (s:multiset<int>)
 66	    ensures (forall i | i in m :: m[i] == A(m)[i]) && (m == map[] <==> A(m) == multiset{}) && (forall i :: i in m <==> i in A(m))
 67	
 68	  // lemma for the opposite of the abstraction function
 69	  lemma LemmaReverseA(m: map<int, nat>, s : seq<int>)
 70	    requires (forall i | i in m :: m[i] == multiset(s)[i]) && (m == map[] <==> multiset(s) == multiset{})
 71	    ensures A(m) == multiset(s)
 72	
 73	  // ADT concrete implementation variable
 74	  var elements: map<int, nat>;
 75	
 76	  // constructor of the implementation class that ensures the implementation invariant
 77	  constructor MultisetImplementationWithMap()
 78	    ensures Valid()
 79	    ensures elements == map[]
 80	    ensures theMultiset == multiset{}
 81	  {
 82	    elements := map[];
 83	    theMultiset := multiset{};
 84	  }
 85	//adds an element to the multiset
 86	  method Add(elem: int) returns (didChange: bool)
 87	    modifies this
 88	    requires Valid()
 89	    ensures elem in elements ==> elements == elements[elem := elements[elem]]
 90	    ensures theMultiset == old(theMultiset) + multiset{elem}
 91	    ensures !(elem in elements) ==> elements == elements[elem := 1]
 92	    ensures didChange
 93	    ensures Contains(elem)
 94	    ensures Valid()
 95	  {
 96	    if !(elem in elements) {
 97	      elements := elements[elem := 1];
 98	    } else {
 99	      elements := elements[elem := (elements[elem] + 1)];
100	    }
101	    
102	    didChange := true;
103	
104	    theMultiset := A(elements);
105	  }
106	
107	//removes an element from the multiset
108	  method Remove(elem: int) returns (didChange: bool)
109	    modifies this
110	    requires Valid()
111	    ensures Valid()
112	   /* If the multiset contains the element */
113	    ensures old(Contains(elem)) ==> theMultiset == old(theMultiset) - multiset{elem}
114	    ensures old(Contains(elem)) ==> didChange
115	    /* If the multiset does not contain the element */
116	    ensures ! old(Contains(elem)) ==> theMultiset == old(theMultiset)
117	    ensures ! old(Contains(elem)) ==> ! didChange
118	    ensures didChange <==> elements != old(elements)
119	  {
120	    /* If the multiset does not contain the element */
121	    if elem !in elements {
122	      assert ! Contains(elem);
123	      assert theMultiset == old(theMultiset);
124	      assert Valid();
125	      return false;
126	    }
127	
128	    /* If the multiset contains the element */
129	    assert Contains(elem);
130	    elements := elements[elem := elements[elem] - 1];
131	
132	    if(elements[elem] == 0) {
133	      elements := elements - {elem};
134	    }
135	
136	    theMultiset := A(elements);
137	    didChange := true;
138	  }
139	
140	//gets the length of the multiset
141	  method Length() returns (len: int)
142	    requires Valid()
143	    ensures len == |theMultiset|
144	  {
145	    var result := Map2Seq(elements);
146	    return |result|;
147	  }
