163	  method getElems() returns (elems: seq<int>)
164	    requires Valid()
165	    ensures Valid()
166	    ensures multiset(elems) == theMultiset
167	  {
168	    var result : seq<int>;
169	    result := Map2Seq(elements);
170	    return result;
171	  }
172	
173	//Transforms a map to a sequence
174	  method Map2Seq(m: map<int, nat>) returns (s: seq<int>)
175	    requires forall i | i in m.Keys :: i in m.Keys <==> m[i] > 0
176	    ensures forall i | i in m.Keys :: multiset(s)[i] == m[i]
177	    ensures forall i | i in m.Keys :: i in s
178	    ensures A(m) == multiset(s)
179	    ensures (forall i | i in m :: m[i] == multiset(s)[i]) && (m == map[] <==> multiset(s) == multiset{})
180	  {
181	    if |m| == 0 {return []; }
182	
183	    var keys := m.Keys;
184	    var key: int;
185	    s := [];
186	
187	    while keys != {}
188	      invariant forall i | i in m.Keys :: i in keys <==> multiset(s)[i] == 0
189	      invariant forall i | i in m.Keys - keys :: multiset(s)[i] == m[i]
190	    {
191	
192	      key :| key in keys;
193	
194	      var counter := 0;
195	
196	      while counter < m[key]
197	        invariant 0 <= counter <= (m[key]) + 1
198	        invariant multiset(s)[key] == counter
199	        invariant forall i | i in m.Keys && i != key :: i in keys <==> multiset(s)[i] == 0
200	        invariant forall i | i in m.Keys - keys :: multiset(s)[i] == m[i];
201	      {
202	        s := s + [key];
203	        counter := counter + 1;
204	      }
205	
206	      keys := keys - {key};
207	
208	    }
209	    LemmaReverseA(m, s);
210	  }
